import json
from pathlib import Path
from typing import Any

import pytest

from risk.summary import TickerSummary, summary_stats
from risk.types import Returns, VolSeries

TESTS = Path(__file__).resolve().parents[2]
TC07 = TESTS / "fixtures" / "risk" / "TC-07"
VOL_SAMPLE = TESTS / "contracts" / "risk.VolSeries" / "sample.json"


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


def _returns(raw: dict[str, Any]) -> Returns:
    return Returns(
        base_date=raw["base_date"],
        dates=tuple(raw["dates"]),
        tickers=tuple(raw["tickers"]),
        values={k: tuple(float(x) for x in v) for k, v in raw["values"].items()},
    )


def _vol(raw: dict[str, Any]) -> VolSeries:
    return VolSeries(
        returns=_returns(raw["returns"]),
        window=int(raw["window"]),
        annualized=bool(raw["annualized"]),
        values={
            k: tuple(None if x is None else float(x) for x in v)
            for k, v in raw["values"].items()
        },
    )


def _tc07() -> tuple[VolSeries, dict[str, Any]]:
    return _vol(_load(TC07 / "input.json")["vol"]), _load(TC07 / "expected.json")


def _by_ticker(rows: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {row.ticker: row for row in rows}


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_order() -> None:
    vol, expected = _tc07()
    rows = summary_stats(vol)
    assert isinstance(rows, tuple)
    assert all(isinstance(r, TickerSummary) for r in rows)
    assert [r.ticker for r in rows] == [e["ticker"] for e in expected["summary"]]


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_fields_match_within_tolerance(field: str) -> None:
    vol, expected = _tc07()
    got = _by_ticker(summary_stats(vol))
    tol = expected["tol"]
    for want in expected["summary"]:
        value = getattr(got[want["ticker"]], field)
        assert value == pytest.approx(want[field], abs=tol), (want["ticker"], field)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe() -> None:
    vol, expected = _tc07()
    got = _by_ticker(summary_stats(vol))
    tol = expected["tol"]
    zero_vol = [e for e in expected["summary"] if e["ann_vol"] == 0.0]
    assert zero_vol
    for want in zero_vol:
        row = got[want["ticker"]]
        assert row.ann_vol == pytest.approx(0.0, abs=tol)
        assert row.sharpe == pytest.approx(want["sharpe"], abs=tol)


@pytest.mark.intent
def test_tc07_last_rolling_volatility_reported() -> None:
    vol, expected = _tc07()
    got = _by_ticker(summary_stats(vol))
    tol = expected["tol"]
    for want in expected["summary"]:
        last = got[want["ticker"]].last_vol
        if want["last_vol"] is None:
            assert last is None
        else:
            assert last is not None
            assert last == pytest.approx(want["last_vol"], abs=tol)


@pytest.mark.intent
def test_periods_per_year_scales_return_linearly_and_vol_by_root() -> None:
    vol, expected = _tc07()
    got = _by_ticker(summary_stats(vol, periods_per_year=63))
    tol = expected["tol"]
    for want in expected["summary"]:
        row = got[want["ticker"]]
        assert row.ann_return == pytest.approx(want["ann_return"] / 4, abs=tol)
        assert row.ann_vol == pytest.approx(want["ann_vol"] / 2, abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("keep", [0, 1])
def test_fewer_than_two_returns_is_value_error(keep: int) -> None:
    raw = _load(VOL_SAMPLE)
    r = raw["returns"]
    r["dates"] = r["dates"][:keep]
    r["values"] = {k: v[:keep] for k, v in r["values"].items()}
    raw["values"] = {k: v[:keep] for k, v in raw["values"].items()}
    with pytest.raises(ValueError, match=r"(?i)two|2|return"):
        summary_stats(_vol(raw))

